L["Action bars (Classic group)"] = "Aktionsleisten (Classic-Gruppe)"
L["Action bars (Retail group)"] = "Aktionsleisten (Retail-Gruppe)"
L["General and Trade too"] = "Auch Allgemein und Handel"
L["Neither NPC speech nor public channels bring chat up"] = "Weder NSC-Sprache noch öffentliche Kanäle holen den Chat hervor"
L["No NPC chatter; speech from behind you shows low on the screen"] = "Kein NSC-Geplauder; Sprache hinter dir erscheint unten am Bildschirm"
L["A portal opens around you as you hearth or teleport"] = "Ein Portal öffnet sich um dich, wenn du den Ruhestein nutzt oder teleportierst"
L["A card shows who buffed you or emoted at you"] = "Eine Karte zeigt, wer dich gebufft oder dir ein Emote geschickt hat"
L["Your race with the top of the meter, in dungeons and raids"] = "Dein Rennen mit der Spitze der Anzeige, in Dungeons und Schlachtzügen"
L["NPC speech brings chat up; public channels don't"] = "NSC-Sprache holt den Chat hervor, öffentliche Kanäle nicht"
L["NPC speech, and the General and Trade channels"] = "NSC-Sprache und die Kanäle Allgemein und Handel"

-- CardMoments.lua, CardsPage.lua, FlightLine.lua: Flight departure
L["Click to target %s"] = "Klicken, um %s ins Ziel zu nehmen"
L["As a flight lands: where it took you, and how long the flight took."] = "Wenn ein Flug landet: wohin er dich gebracht hat und wie lange er gedauert hat."
L["Flight departure"] = "Abflug"
L["As a flight takes off: where it's taking you, and about how long it takes on a route you've flown before. With a line along the top or bottom of the screen filling up on the way, if you like."] = "Wenn ein Flug startet: wohin er dich bringt und, auf einer schon geflogenen Route, etwa wie lange er dauert. Auf Wunsch mit einer Linie am oberen oder unteren Bildschirmrand, die sich unterwegs füllt."
L["Flying to"] = "Flug nach"
L["First time on this route"] = "Erstes Mal auf dieser Route"
L["about %d min"] = "etwa %d Min."
L["%s flight"] = "%s Flug"
L["Progress line"] = "Fortschrittslinie"
L["Show a line as you fly"] = "Beim Fliegen eine Linie zeigen"
L["On a route you've flown before, a thin line along a letterbox bar (or that edge of the screen) fills up as you fly, with the time left at its end. It shows while your UI is faded, and goes a moment before you land. A route's first flight has none: it's timed as you fly it."] = "Auf einer schon geflogenen Route füllt sich beim Fliegen eine dünne Linie entlang eines Letterbox-Balkens (oder dieses Bildschirmrands), mit der verbleibenden Zeit am Ende. Sie erscheint, während dein UI ausgeblendet ist, und verschwindet kurz vor der Landung. Der erste Flug einer Route hat keine: Er wird beim Fliegen gemessen."
L["Flight progress line"] = "Flugfortschrittslinie"
L["Top bar"] = "Oberer Balken"
L["Only at the start and end"] = "Nur am Anfang und Ende"
L["The line shows for this long as the flight starts and before it lands, and is hidden in between: point the mouse at its place to see it. 0: it shows the whole way."] = "Die Linie erscheint so lange zu Beginn des Flugs und vor der Landung und ist dazwischen verborgen: Zeig mit der Maus auf ihren Platz, um sie zu sehen. 0: Sie ist die ganze Zeit zu sehen."
L["Bottom bar"] = "Unterer Balken"
L["The letterbox bar the line and its time go in (no letterbox up: that edge of the screen)."] = "Der Letterbox-Balken, in dem die Linie und ihre Zeit erscheinen (ohne Letterbox: dieser Bildschirmrand)."
L["Not on flights"] = "Nicht auf Flügen"
L["No Zone or Subzone card on a flight path: the places you fly over don't bring one after another, and the Flight departure and arrival cards say where you're going."] = "Keine Zonen- oder Unterzonen-Karte auf einer Flugroute: Die Orte, über die du fliegst, bringen nicht eine nach der anderen, und die Karten für Abflug und Ankunft sagen, wohin es geht."
L["Minutes only"] = "Nur Minuten"
L["\"2 min\", rounded up, then \"under a minute\"."] = "\"2 Min.\", aufgerundet, dann \"unter einer Minute\"."
L["Minutes and seconds"] = "Minuten und Sekunden"
L["\"1:12\", counting down."] = "\"1:12\", rückwärts zählend."
L["Don't show"] = "Nicht zeigen"
L["Just the line."] = "Nur die Linie."
L["Time left:"] = "Verbleibende Zeit:"
L["The time left at the line's end."] = "Die verbleibende Zeit am Ende der Linie."
L["The Flight departure card's line is on: on a route you've flown before, it fills up as you fly"] = "Die Linie der Abflugkarte ist an: Auf einer schon geflogenen Route füllt sie sich beim Fliegen"
L["Where:"] = "Wo:"

