-- UI/GridRows.lua
L["Dead target"] = "Totes Ziel"
L["On a flight path"] = "Auf einer Flugroute"
L["CQL is the words a rule is written in, joined with AND, OR and NOT."] = "CQL sind die Wörter, in denen eine Regel geschrieben ist, verbunden mit AND, OR und NOT."
L["Adds \"%s\": true for a tooltip of this kind."] = "Fügt „%s“ hinzu: wahr für einen Tooltip dieser Art."
L["Adds \"%s\"; a green dot means it's true where you are now."] = "Fügt „%s“ hinzu; ein grüner Punkt heißt, es ist dort wahr, wo du gerade bist."
L["Out of fights only."] = "Nur außerhalb von Kämpfen."
L["The rule isn't finished; finish it or press Escape to undo."] = "Die Regel ist nicht fertig; stell sie fertig oder drück Escape, um sie rückgängig zu machen."
L["Makes this row show whenever another row of its table does, instead of a rule."] = "Lässt diese Zeile statt einer Regel immer dann zeigen, wenn eine andere Zeile ihrer Tabelle zeigt."
L["Green: it would show in CineMode now; gray: hidden; none: rule not finished."] = "Grün: würde jetzt in CineMode zeigen; grau: verborgen; keiner: Regel nicht fertig."
L["Follows %s and shows when it does."] = "Folgt %s und zeigt, wenn es zeigt."
